import { Gherkin, it, makeFeature, Then, When } from '@systemfsoftware/effect-gherkin-spec'
import type { RunEvent } from '@systemfsoftware/stryker-js'
import type { Check, Expect } from '@systemfsoftware/vitest'
import { Effect } from 'effect'
import { normalizeCounts } from '../scripts/oracle/normalize.js'
import type { ExecResult } from '../src/Harness/guest-job.schema.js'
import { E2eHarnessLive, runStryker } from './__fixtures__/e2e-harness.fixture.js'
import { decodeStream, verdictOrUndefined } from './__fixtures__/machine-stream.fixture.js'

// ORACLE-LITERALS:BEGIN — generated by `pnpm derive-oracle --reconcile`. Do not edit inside the markers.
const RESILIENCE_COUNTS: {
  readonly compileErrors: number
  readonly ignored: number
  readonly killedOrTimeout: number
  readonly noCoverage: number
  readonly pending: number
  readonly runtimeErrors: number
  readonly survived: number
} = {
  compileErrors: 14,
  ignored: 0,
  killedOrTimeout: 25,
  noCoverage: 0,
  pending: 0,
  runtimeErrors: 0,
  survived: 15,
}
// ORACLE-LITERALS:END

const ENTERPRISE_FIXTURE_URL = new URL('../testResources/enterprise-monorepo-fixture', import.meta.url)

const verifyResilienceCounts = (
  expect: Expect,
  run: ExecResult,
  events: ReadonlyArray<RunEvent.RunEvent>,
  verdict: RunEvent.VerdictReached | undefined,
): Check => {
  const normalized = verdict === undefined ? undefined : normalizeCounts(verdict.counts)
  const timeouts = events
    .filter((event): event is Extract<RunEvent.RunEvent, { _tag: 'mutantTested' }> => event._tag === 'mutantTested')
    .filter((mutant) => mutant.status === 'Timeout')
  const trapTimeouts = timeouts.filter((mutant) => mutant.fileName.includes('nontermination.ts'))

  return expect({
    exitCode: run.exitCode,
    verdictIsPresent: verdict !== undefined,
    ignored: normalized?.ignored,
    noCoverage: normalized?.noCoverage,
    pending: normalized?.pending,
    runtimeErrors: normalized?.runtimeErrors,
    trapTimeoutsAreReported: trapTimeouts.length > 0,
    everyTimeoutIsATrap: timeouts.length === trapTimeouts.length,
  }).toStrictEqual({
    exitCode: 0,
    verdictIsPresent: true,
    ignored: RESILIENCE_COUNTS.ignored,
    noCoverage: RESILIENCE_COUNTS.noCoverage,
    pending: RESILIENCE_COUNTS.pending,
    runtimeErrors: RESILIENCE_COUNTS.runtimeErrors,
    trapTimeoutsAreReported: true,
    everyTimeoutIsATrap: true,
  })
}

const Feature = makeFeature({ it })

Feature('Surviving worker timeouts and concurrency in an enterprise fixture', { timeout: 900_000 })
  .withLayer(E2eHarnessLive)
  .live(
    'boots a warm microVM for the enterprise fixture and runs the packed CLI, exporting host and worker spans to the Grafana LGTM collector',
  )
  .body(({ scenario }) => {
    scenario(
      'A run with resilience and timeout configuration reports the trap timeout',
      Gherkin.Do.pipe(
        When('the CLI executes with resilience and timeout configuration')(
          'run',
          () =>
            runStryker({
              fixture: ENTERPRISE_FIXTURE_URL,
              label: 'enterprise-resilience-fixture',
              args: ['run', 'stryker.resilience.config.ts'],
            }),
        ),
        When('the stdout event stream decodes to run events')(
          'events',
          (s) => decodeStream(s.run.output.result.stdout),
        ),
        When('the terminal verdict of the decoded stream is read')(
          'verdict',
          (s) => Effect.succeed(verdictOrUndefined(s.events)),
        ),
        Then('the named trap is Timeout and clock counts are not pinned')((s, expect) =>
          verifyResilienceCounts(expect, s.run.output.result, s.events, s.verdict)
        ),
      ),
    )
  })
